<?php
$stock=($_GET['mode']??'')==='stock';$q=trim(substr((string)($_GET['q']??''),0,200));$where=[];$args=[];$from=$stock?' FROM stock_events a LEFT JOIN products p ON p.id=a.product_id LEFT JOIN users u ON u.id=a.user_id':' FROM activity_log a LEFT JOIN users u ON u.id=a.user_id';
if($q!==''){$where[]=$stock?'(p.name LIKE ? OR p.master_sku LIKE ? OR a.reference_no LIKE ? OR a.action_type LIKE ?)':'(a.action_type LIKE ? OR a.entity_ref LIKE ? OR a.details LIKE ? OR u.name LIKE ?)';$args=array_fill(0,4,'%'.$q.'%');}if(!empty($_GET['user_id'])){$where[]='a.user_id=?';$args[]=(int)$_GET['user_id'];}foreach(['date_from'=>'>=','date_to'=>'<='] as $key=>$op)if(!empty($_GET[$key])){$d=DateTime::createFromFormat('!Y-m-d',$_GET[$key]);if($d&&$d->format('Y-m-d')===$_GET[$key]){$where[]=($stock?'a.txn_date':'DATE(a.created_at)').$op.'?';$args[]=$_GET[$key];}}
if($stock&&!empty($_GET['platform'])){$where[]='a.platform=?';$args[]=$_GET['platform'];}if($stock&&($_GET['status']??'')==='negative')$where[]='a.after_qty<0';if(!$stock)$where[]="LOWER(a.action_type) NOT IN ('login','logout')";$from.=($where?' WHERE '.implode(' AND ',$where):'');$count=db()->prepare('SELECT COUNT(*)'.$from);$count->execute($args);$total=(int)$count->fetchColumn();$offset=max(0,(int)($_GET['offset']??0));$offset=$total?min($offset,(int)(floor(($total-1)/50)*50)):0;
echo '<div class="page-head"><div><h1>'.($stock?'Stock Movement History':'Activity Log').'</h1><p>Search references, products, dates and processors. Original records are preserved.</p></div></div><div class="tabs"><a class="tab '.(!$stock?'active':'').'" href="?page=activity">Activity</a><a class="tab '.($stock?'active':'').'" href="?page=activity&mode=stock">Stock Movements</a></div><div class="card"><form method="get" class="inflow-search-form"><input type="hidden" name="page" value="activity"><input type="hidden" name="mode" value="'.($stock?'stock':'activity').'"><label>Search<input name="q" value="'.e($q).'" placeholder="Order ID, reference, product / SKU or action"></label><label>From<input type="date" name="date_from" value="'.e($_GET['date_from']??'').'"></label><label>To<input type="date" name="date_to" value="'.e($_GET['date_to']??'').'"></label><label>Processed By<select name="user_id"><option value="">All users</option>';foreach(db()->query('SELECT id,name FROM users ORDER BY name') as $u)echo '<option value="'.$u['id'].'" '.((int)($_GET['user_id']??0)===$u['id']?'selected':'').'>'.e($u['name']).'</option>';echo '</select></label>';if($stock){echo '<label>Platform<select name="platform"><option value="">All platforms</option>';foreach(['Shopee','Lazada','TikTok'] as $p)echo '<option '.(($_GET['platform']??'')===$p?'selected':'').'>'.$p.'</option>';echo '</select></label><label>Result<select name="status"><option value="">All results</option><option value="negative" '.(($_GET['status']??'')==='negative'?'selected':'').'>Negative after movement</option></select></label>';}echo '<button class="btn secondary">Search</button><a class="btn ghost" href="?page=activity'.($stock?'&mode=stock':'').'">Clear Filters</a></form></div><div class="card table-wrap"><p>'.$total.' records · '.($total?$offset+1:0).'–'.min($offset+50,$total).'</p><table class="table"><tr><th>Date / Time</th><th>Processed By</th><th>Action</th><th>Reference / Product</th><th>Details</th></tr>';
$query=db()->prepare('SELECT a.*,u.name user_name'.($stock?',p.name product_name,p.master_sku':'').$from.' ORDER BY a.id DESC LIMIT 50 OFFSET '.$offset);$query->execute($args);foreach($query as $r)echo '<tr><td>'.e(date('M d, Y H:i',strtotime($r['created_at']))).($stock?'<br>Txn: '.e($r['txn_date']):'').'</td><td>'.e($r['user_name']??'Scheduled Backup').'</td><td>'.e($r['action_type']).'</td><td>'.e($stock?($r['reference_no'].' · '.$r['master_sku'].' · '.$r['product_name']):$r['entity_ref']).'</td><td>'.e($stock?($r['platform'].': '.$r['before_qty'].' → '.$r['after_qty'].' pcs ('.sprintf('%+d',$r['after_qty']-$r['before_qty']).')'):$r['details']).'</td></tr>';if(!$total)echo '<tr><td colspan="5">No records match these filters.</td></tr>';echo '</table></div><div class="modal-actions">';echo rs8_pagination($total,$offset,50,array_replace($_GET,['page'=>'activity']));echo '</div>';
